import java.io.*;
import java.net.http.*;
import java.net.URI;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import com.sun.net.httpserver.*;

public class ConfigService {
    private static final String MASTER_KEY_ENV = "MASTER_KEY";
    private static final String DATA_DIR = "/var/lib/configsvc/data";
    private static final Map<String, String> sessionStore = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new java.net.InetSocketAddress(8080), 0);
        server.createContext("/api/config/export", ConfigService::handleExport);
        server.createContext("/api/config/import", ConfigService::handleImport);
        server.createContext("/api/health", ConfigService::handleHealth);
        server.setExecutor(Executors.newFixedThreadPool(4));
        server.start();
    }

    static void handleHealth(HttpExchange ex) throws IOException {
        ex.sendResponseHeaders(200, 2);
        ex.getResponseBody().write("OK".getBytes());
        ex.close();
    }

    // Export config as encrypted archive
    static void handleExport(HttpExchange ex) throws IOException {
        if (!"POST".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, 0); ex.close(); return;
        }
        String authToken = ex.getRequestHeaders().getFirst("X-Auth-Token");
        if (authToken == null || !sessionStore.containsKey(authToken)) {
            ex.sendResponseHeaders(401, 0); ex.close(); return;
        }

        // Read request body for config path
        String body = new String(ex.getRequestBody().readAllBytes());
        Properties props = new Properties();
        props.load(new StringReader(body));

        String configPath = props.getProperty("path", "default");
        String format = props.getProperty("format", "tar");

        // Validate path doesn't escape data directory
        // Using canonical path check for safety
        File targetDir = new File(DATA_DIR, configPath);
        if (!targetDir.getCanonicalPath().startsWith(new File(DATA_DIR).getCanonicalPath())) {
            ex.sendResponseHeaders(403, 0); ex.close(); return;
        }

        // Build archive command based on format
        String archiveCmd;
        if ("zip".equals(format)) {
            archiveCmd = String.format("zip -r /tmp/export.zip %s", targetDir.getCanonicalPath());
        } else {
            // tar format - user can specify compression via 'compress' property
            String compressFlag = props.getProperty("compress", "gz");
            // VULNERABILITY: compressFlag is injected directly into shell command
            // Intended values: gz, bz2, xz, zstd
            // The regex check below is intentionally flawed - it checks the flag
            // starts with a valid value but doesn't anchor the end
            if (!compressFlag.matches("^(gz|bz2|xz|zstd).*")) {
                compressFlag = "gz";
            }
            archiveCmd = String.format(
                "tar -c --%s -f /tmp/export.tar.%s %s",
                compressFlag, compressFlag, targetDir.getCanonicalPath()
            );
        }

        try {
            Process proc = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", archiveCmd});
            int exitCode = proc.waitFor();
            if (exitCode == 0) {
                byte[] archive = Files.readAllBytes(Path.of("/tmp/export.tar." + props.getProperty("compress", "gz")));
                byte[] encrypted = encryptPayload(archive);
                ex.getResponseHeaders().set("Content-Type", "application/octet-stream");
                ex.sendResponseHeaders(200, encrypted.length);
                ex.getResponseBody().write(encrypted);
            } else {
                byte[] err = proc.getErrorStream().readAllBytes();
                ex.sendResponseHeaders(500, err.length);
                ex.getResponseBody().write(err);
            }
        } catch (Exception e) {
            byte[] msg = e.getMessage().getBytes();
            ex.sendResponseHeaders(500, msg.length);
            ex.getResponseBody().write(msg);
        }
        ex.close();
    }

    static void handleImport(HttpExchange ex) throws IOException {
        // Import handler - reads encrypted archive and extracts
        if (!"POST".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, 0); ex.close(); return;
        }
        String authToken = ex.getRequestHeaders().getFirst("X-Auth-Token");
        if (authToken == null || !sessionStore.containsKey(authToken)) {
            ex.sendResponseHeaders(401, 0); ex.close(); return;
        }
        byte[] encrypted = ex.getRequestBody().readAllBytes();
        try {
            byte[] decrypted = decryptPayload(encrypted);
            Files.write(Path.of("/tmp/import.tar.gz"), decrypted);
            Process proc = Runtime.getRuntime().exec(new String[]{
                "/bin/sh", "-c", "tar -xzf /tmp/import.tar.gz -C " + DATA_DIR
            });
            proc.waitFor();
            ex.sendResponseHeaders(200, 2);
            ex.getResponseBody().write("OK".getBytes());
        } catch (Exception e) {
            ex.sendResponseHeaders(500, 0);
        }
        ex.close();
    }

    static byte[] encryptPayload(byte[] data) throws Exception {
        String key = System.getenv(MASTER_KEY_ENV);
        SecretKeySpec spec = new SecretKeySpec(key.getBytes(), 0, 16, "AES");
        Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, spec);
        return cipher.doFinal(data);
    }

    static byte[] decryptPayload(byte[] data) throws Exception {
        String key = System.getenv(MASTER_KEY_ENV);
        SecretKeySpec spec = new SecretKeySpec(key.getBytes(), 0, 16, "AES");
        Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, spec);
        return cipher.doFinal(data);
    }
}
